2	
3	import (
4		"encoding/json"
5		"fmt"
6		"os"
7		"path/filepath"
8	)
9	
10	// save 将状态原子写入状态文件：先写临时文件并 fsync，再 rename 覆盖，
11	// 最后 fsync 目录。崩溃只会留下旧文件或新文件之一，不会出现半截状态。
12	func (n *Node) save(st *state) error {
13		if n.injectSaveErr != nil {
14			return n.injectSaveErr
15		}
16		raw, err := json.MarshalIndent(st, "", "  ")
17		if err != nil {
18			return fmt.Errorf("encode state: %w", err)
19		}
20		dir := n.dir
21		tmp := filepath.Join(dir, stateFileName+".tmp")
22		final := filepath.Join(dir, stateFileName)
23		f, err := os.OpenFile(tmp, os.O_CREATE|os.O_WRONLY|os.O_TRUNC, 0o644)
24		if err != nil {
25			return fmt.Errorf("create state temp file: %w", err)
26		}
27		if _, err := f.Write(raw); err != nil {
28			f.Close()
29			os.Remove(tmp)
30			return fmt.Errorf("write state: %w", err)
31		}
32		if err := f.Sync(); err != nil {
33			f.Close()
34			os.Remove(tmp)
35			return fmt.Errorf("sync state: %w", err)
36		}
37		if err := f.Close(); err != nil {
38			os.Remove(tmp)
39			return fmt.Errorf("close state: %w", err)
40		}
41		if err := os.Rename(tmp, final); err != nil {
42			os.Remove(tmp)
43			return fmt.Errorf("commit state: %w", err)
44		}
45		if d, err := os.Open(dir); err == nil {
46			_ = d.Sync()
47			_ = d.Close()
48		}
49		return nil
50	}
51	
52	// clone 深拷贝完整状态，使一次确认可以先在副本上完整应用、原子落盘成功后再替换内存。
53	func (s *state) clone() *state {
54		c := &state{
55			Version:   s.Version,
56			Seed:      append([]byte(nil), s.Seed...),
57			MaxTxs:    s.MaxTxs,
58			Capacity:  s.Capacity,
59			Round:     s.Round,
60			LastBlock: s.LastBlock,
61			Accounts:  make(map[string]uint64, len(s.Accounts)),
62			Pool:      make(map[string]map[uint64]string, len(s.Pool)),
63			Entries:   make(map[string]*poolEntry, len(s.Entries)),
64			Confirmed: make(map[string]confirmedRef, len(s.Confirmed)),
65			Blocks:    make([]Block, len(s.Blocks)),
66		}
67		c.Validators = make([][]byte, len(s.Validators))
68		for i, v := range s.Validators {
69			c.Validators[i] = append([]byte(nil), v...)
70		}
71		for k, v := range s.Accounts {
72			c.Accounts[k] = v
73		}
74		for sender, seqs := range s.Pool {
75			m := make(map[uint64]string, len(seqs))
76			for seq, id := range seqs {
77				m[seq] = id
78			}
79			c.Pool[sender] = m
80		}
81		for id, e := range s.Entries {
82			c.Entries[id] = &poolEntry{
83				Tx:         copyTx(e.Tx),
84				Status:     e.Status,
85				ReplacedBy: e.ReplacedBy,
86				DropReason: e.DropReason,
87				DropRound:  e.DropRound,
88			}
89		}
90		for id, ref := range s.Confirmed {
91			c.Confirmed[id] = ref
92		}
93		for i, b := range s.Blocks {
94			c.Blocks[i] = Block{
95				Height:     b.Height,
96				Round:      b.Round,
97				ID:         b.ID,
98				PreviousID: b.PreviousID,
99				TxIDs:      append([]string(nil), b.TxIDs...),
100			}
101		}
102		if s.Proposal != nil {
103			c.Proposal = &proposalState{
104				Round:   s.Proposal.Round,
105				TxIDs:   append([]string(nil), s.Proposal.TxIDs...),
106				BlockID: s.Proposal.BlockID,
107				Votes:   append([]string(nil), s.Proposal.Votes...),
108			}
109		}
110		c.Rounds = make(map[uint64]*roundState, len(s.Rounds))
111		for r, rs := range s.Rounds {
112			cr := &roundState{
113				Round:          rs.Round,
114				Height:         rs.Height,
115				PreviousID:     rs.PreviousID,
116				LocalBlockID:   rs.LocalBlockID,
117				Ended:          rs.Ended,
118				EndedByConfirm: rs.EndedByConfirm,
119				DetailMissing:  rs.DetailMissing,
120				Candidates:     make(map[string]*candidateState, len(rs.Candidates)),
121			}
122			for id, cand := range rs.Candidates {
123				cr.Candidates[id] = &candidateState{
124					TxIDs:   append([]string(nil), cand.TxIDs...),
125					BlockID: cand.BlockID,
126					Votes:   append([]string(nil), cand.Votes...),
127					Local:   cand.Local,
128					Decided: cand.Decided,
